/**
 * DWS CLI executor — the only place in WorkHub that spawns `dws`.
 *
 * Guarantees (per WorkHub technical design §4.2):
 *  - no shell string concatenation; argv only, generated by DwsClient whitelists
 *  - timeout + child kill
 *  - stdout size cap
 *  - bounded concurrency queue
 *  - tolerant JSON extraction (dws may print `# info:` banner lines before JSON)
 *  - classified errors
 */
import { execFile } from 'node:child_process'

const DEFAULT_TIMEOUT_MS = 30_000
const MAX_STDOUT_BYTES = 8 * 1024 * 1024
const MAX_CONCURRENCY = 3

export class DwsExecutor {
  constructor(options = {}) {
    this.bin = options.bin ?? 'dws'
    this.timeoutMs = options.timeoutMs ?? DEFAULT_TIMEOUT_MS
    this.maxStdoutBytes = options.maxStdoutBytes ?? MAX_STDOUT_BYTES
    this.maxConcurrency = options.maxConcurrency ?? MAX_CONCURRENCY
    this._active = 0
    this._queue = []
  }

  /** Run `dws ...args --format json` and return parsed JSON. */
  async execute(args, options = {}) {
    const fullArgs = [...args, '--format', 'json']
    return this._run(fullArgs, options)
  }

  /** Run raw argv without the implicit --format json. */
  async runRaw(args, options = {}) {
    return this._run(args, options)
  }

  _enqueue() {
    if (this._active < this.maxConcurrency) {
      this._active++
      return Promise.resolve()
    }
    return new Promise((resolve) => this._queue.push(resolve))
  }

  _dequeue() {
    const next = this._queue.shift()
    if (next) {
      next()
    } else {
      this._active--
    }
  }

  async _run(args, { timeoutMs, signal } = {}) {
    await this._enqueue()
    try {
      return await this._spawn(args, timeoutMs ?? this.timeoutMs, signal)
    } finally {
      this._dequeue()
    }
  }

  _spawn(args, timeoutMs, externalSignal) {
    return new Promise((resolve, reject) => {
      let child
      try {
        child = execFile(
          this.bin,
          args,
          { timeout: timeoutMs, killSignal: 'SIGKILL', maxBuffer: this.maxStdoutBytes, windowsHide: true },
          (error, stdout, stderr) => {
            if (error) {
              if (error.killed || error.signal === 'SIGKILL') {
                reject(classifyError('dws-timeout', `dws timed out after ${timeoutMs}ms: ${args.join(' ')}`))
              } else if (error.code === 'ENOENT') {
                reject(classifyError('dws-not-installed', 'dws CLI not found on PATH'))
              } else {
                reject(classifyError('dws-exit', trim(stderr || error.message)))
              }
              return
            }
            try {
              resolve(extractJson(stdout))
            } catch (e) {
              reject(classifyError('dws-invalid-json', trim(stdout) || String(e?.message || e)))
            }
          },
        )
      } catch (e) {
        reject(classifyError('dws-spawn', String(e?.message || e)))
        return
      }
      const aborted = () => {
        try {
          child.kill('SIGKILL')
        } catch {}
        reject(classifyError('aborted', 'request aborted'))
      }
      if (externalSignal) {
        if (externalSignal.aborted) {
          aborted()
          return
        }
        externalSignal.addEventListener('abort', aborted, { once: true })
        child.on('close', () => externalSignal.removeEventListener('abort', aborted))
      }
    })
  }
}

function extractJson(stdout) {
  if (typeof stdout !== 'string') return stdout
  const start = stdout.search(/[{[]/)
  const text = start > 0 ? stdout.slice(start) : stdout
  const parsed = JSON.parse(text)
  // dws error envelope: { "error": { code, message, ... } }
  if (parsed && typeof parsed === 'object' && !Array.isArray(parsed) && parsed.error) {
    const err = parsed.error
    const code = String(err.category || err.code || err.reason || 'dws-error')
    if (code !== 'validation' || !parsed.success) {
      throw classifyError(code, String(err.message || err.hint || 'dws error'))
    }
  }
  return parsed
}

function classifyError(code, message) {
  const e = new Error(message)
  e.code = code
  return e
}

function trim(text) {
  const s = String(text ?? '').trim()
  return s.length > 300 ? `${s.slice(0, 300)}…` : s
}
